//! The rules of the fields of an API schema (`length`, `email`, `siren`), checked by the HTTP routes before
//! any step runs. Each returns the message of the 400, which names the field.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

/// Between `min` and `max` **characters** (not bytes), once trimmed.
pub fn length(field: &str, value: &str, min: u32, max: u32) -> Result<(), String> {
    let len = value.trim().chars().count();
    if (min as usize..=max as usize).contains(&len) {
        Ok(())
    } else {
        Err(format!("{field}: between {min} and {max} characters"))
    }
}

/// `local@domain.tld`, 254 characters at most. A syntax check: only a message sent to the address says whether
/// it exists.
pub fn email(field: &str, value: &str) -> Result<(), String> {
    let value = value.trim();
    let valid = value.chars().count() <= 254
        && value.split_once('@').is_some_and(|(local, domain)| {
            !local.is_empty()
                && !domain.contains('@')
                && domain.contains('.')
                && !domain.starts_with('.')
                && !domain.ends_with('.')
                && !value.chars().any(char::is_whitespace)
        });
    if valid {
        Ok(())
    } else {
        Err(format!("{field}: invalid e-mail address"))
    }
}

/// A French company number: 9 digits and a valid Luhn check digit.
pub fn siren(field: &str, value: &str) -> Result<(), String> {
    let digits: Vec<u32> = value.chars().filter_map(|c| c.to_digit(10)).collect();
    if value.chars().count() != 9 || digits.len() != 9 {
        return Err(format!("{field}: 9 digits expected"));
    }
    let sum: u32 = digits
        .iter()
        .rev()
        .enumerate()
        .map(|(i, &d)| {
            if i % 2 == 1 {
                let doubled = d * 2;
                if doubled > 9 { doubled - 9 } else { doubled }
            } else {
                d
            }
        })
        .sum();
    if sum % 10 == 0 {
        Ok(())
    } else {
        Err(format!("{field}: invalid check digit"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn email_rules() {
        assert!(email("email", "a@b.fr").is_ok());
        assert!(email("email", " a@b.fr ").is_ok(), "trimmed");
        for bad in [
            "",
            "a",
            "@b.fr",
            "a@b",
            "a@b.",
            "a@.fr",
            "a b@c.fr",
            "a@b@c.fr",
            &format!("{}@b.fr", "a".repeat(260)),
        ] {
            let error = email("email", bad).unwrap_err();
            assert_eq!(error, "email: invalid e-mail address", "{bad}");
        }
    }

    #[test]
    fn length_counts_characters_not_bytes_and_trims() {
        assert!(length("name", "Al", 2, 5).is_ok());
        // 10 characters, 20 bytes.
        assert!(length("password", "éééééééééé", 10, 128).is_ok());
        assert_eq!(
            length("name", " A ", 2, 5).unwrap_err(),
            "name: between 2 and 5 characters",
            "trimmed before counting"
        );
        assert!(length("name", "Alexandre", 2, 5).is_err());
        // A password of the maximum, and one more.
        assert!(length("password", &"a".repeat(128), 10, 128).is_ok());
        assert!(length("password", &"a".repeat(129), 10, 128).is_err());
    }

    #[test]
    fn siren_needs_nine_digits_and_the_luhn_check() {
        assert!(siren("siren", "732829320").is_ok(), "a public SIREN");
        assert_eq!(siren("siren", "732829321").unwrap_err(), "siren: invalid check digit");
        for bad in ["12345678", "1234567890", "73282932a", "", "٧٣٢٨٢٩٣٢٠"] {
            assert_eq!(siren("siren", bad).unwrap_err(), "siren: 9 digits expected", "{bad}");
        }
    }
}
